import { forwardRef } from 'react';
import {
  LineChart as RCLineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  BarChart as RCBarChart, Bar,
  AreaChart as RCAreaChart, Area,
  PieChart as RCPieChart, Pie, Cell
} from 'recharts';
import { TrendingUp, TrendingDown } from 'lucide-react';

const COLORS = ['#8b5cf6', '#06b6d4', '#10b981', '#f59e0b', '#ef4444', '#ec4899'];
const CHART_CONTAINER = 'backdrop-blur-xl bg-white/5 border border-white/10 rounded-2xl p-6';
const TOOLTIP_STYLE = {
  backgroundColor: 'rgba(15, 23, 42, 0.95)',
  border: '1px solid rgba(255, 255, 255, 0.1)',
  borderRadius: '12px',
  boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04)',
};
const GRID_STROKE = 'rgba(255, 255, 255, 0.05)';
const AXIS_STROKE = 'rgba(255, 255, 255, 0.15)';
const TEXT_COLOR = '#94a3b8';

interface ChartData {
  name: string;
  [key: string]: string | number;
}

interface BaseChartProps {
  data: ChartData[];
  xKey: string;
  yKeys: string[];
  colors?: string[];
  height?: number;
  showLegend?: boolean;
  showGrid?: boolean;
  className?: string;
}

export const LineChart = forwardRef<HTMLDivElement, BaseChartProps & { smooth?: boolean }>(
  ({ className = '', data, xKey, yKeys, colors = COLORS, height = 300, showLegend = true, showGrid = true, smooth = true, ...props }, ref) => (
    <div ref={ref} className={`${CHART_CONTAINER} ${className}`} {...props}>
      <ResponsiveContainer width="100%" height={height}>
        <RCLineChart data={data} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
          {showGrid && <CartesianGrid strokeDasharray="3 3" stroke={GRID_STROKE} vertical={false} />}
          <XAxis dataKey={xKey} stroke={AXIS_STROKE} tick={{ fill: TEXT_COLOR, fontSize: 12 }} axisLine={false} tickLine={false} />
          <YAxis stroke={AXIS_STROKE} tick={{ fill: TEXT_COLOR, fontSize: 12 }} axisLine={false} tickLine={false} />
          <Tooltip contentStyle={TOOLTIP_STYLE} labelStyle={{ color: '#e2e8f0' }} itemStyle={{ color: '#e2e8f0' }} />
          {showLegend && <Legend wrapperStyle={{ paddingTop: 20 }} />}
          {yKeys.map((key, i) => (
            <Line
              key={key}
              type={smooth ? 'monotone' : 'linear'}
              dataKey={key}
              stroke={colors[i % colors.length]}
              strokeWidth={2}
              dot={{ r: 4, strokeWidth: 2, fill: '#0a0e1a' }}
              activeDot={{ r: 6, strokeWidth: 2 }}
            />
          ))}
        </RCLineChart>
      </ResponsiveContainer>
    </div>
  )
);
LineChart.displayName = 'LineChart';

export const BarChart = forwardRef<HTMLDivElement, BaseChartProps & { stacked?: boolean }>(
  ({ className = '', data, xKey, yKeys, colors = COLORS, height = 300, showLegend = true, showGrid = true, stacked = false, ...props }, ref) => (
    <div ref={ref} className={`${CHART_CONTAINER} ${className}`} {...props}>
      <ResponsiveContainer width="100%" height={height}>
        <RCBarChart data={data} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
          {showGrid && <CartesianGrid strokeDasharray="3 3" stroke={GRID_STROKE} vertical={false} />}
          <XAxis dataKey={xKey} stroke={AXIS_STROKE} tick={{ fill: TEXT_COLOR, fontSize: 12 }} axisLine={false} tickLine={false} />
          <YAxis stroke={AXIS_STROKE} tick={{ fill: TEXT_COLOR, fontSize: 12 }} axisLine={false} tickLine={false} />
          <Tooltip contentStyle={TOOLTIP_STYLE} labelStyle={{ color: '#e2e8f0' }} itemStyle={{ color: '#e2e8f0' }} />
          {showLegend && <Legend wrapperStyle={{ paddingTop: 20 }} />}
          {yKeys.map((key, i) => (
            <Bar
              key={key}
              dataKey={key}
              fill={colors[i % colors.length]}
              radius={[6, 6, 0, 0]}
              stackId={stacked ? 'a' : undefined}
            />
          ))}
        </RCBarChart>
      </ResponsiveContainer>
    </div>
  )
);
BarChart.displayName = 'BarChart';

export const AreaChart = forwardRef<HTMLDivElement, BaseChartProps & { stacked?: boolean }>(
  ({ className = '', data, xKey, yKeys, colors = COLORS, height = 300, showLegend = true, showGrid = true, stacked = false, ...props }, ref) => (
    <div ref={ref} className={`${CHART_CONTAINER} ${className}`} {...props}>
      <ResponsiveContainer width="100%" height={height}>
        <RCAreaChart data={data} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
          {showGrid && <CartesianGrid strokeDasharray="3 3" stroke={GRID_STROKE} vertical={false} />}
          <XAxis dataKey={xKey} stroke={AXIS_STROKE} tick={{ fill: TEXT_COLOR, fontSize: 12 }} axisLine={false} tickLine={false} />
          <YAxis stroke={AXIS_STROKE} tick={{ fill: TEXT_COLOR, fontSize: 12 }} axisLine={false} tickLine={false} />
          <Tooltip contentStyle={TOOLTIP_STYLE} labelStyle={{ color: '#e2e8f0' }} itemStyle={{ color: '#e2e8f0' }} />
          {showLegend && <Legend wrapperStyle={{ paddingTop: 20 }} />}
          {yKeys.map((key, i) => (
            <Area
              key={key}
              type="monotone"
              dataKey={key}
              stroke={colors[i % colors.length]}
              fill={colors[i % colors.length]}
              fillOpacity={0.3}
              strokeWidth={2}
              stackId={stacked ? 'a' : undefined}
            />
          ))}
        </RCAreaChart>
      </ResponsiveContainer>
    </div>
  )
);
AreaChart.displayName = 'AreaChart';

export const PieChart = forwardRef<HTMLDivElement, { data: ChartData[]; nameKey: string; valueKey: string; colors?: string[]; height?: number; className?: string }>(
  ({ className = '', data, nameKey, valueKey, colors = COLORS, height = 300, ...props }, ref) => (
    <div ref={ref} className={`${CHART_CONTAINER} ${className}`} {...props}>
      <ResponsiveContainer width="100%" height={height}>
        <RCPieChart>
          <Pie
            data={data}
            cx="50%"
            cy="50%"
            innerRadius={60}
            outerRadius={100}
            dataKey={valueKey}
            nameKey={nameKey}
            label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
            labelLine={false}
            labelStyle={{ fill: '#e2e8f0', fontSize: 12 }}
          >
            {data.map((_, i) => (
              <Cell key={`cell-${i}`} fill={colors[i % colors.length]} />
            ))}
          </Pie>
          <Tooltip contentStyle={TOOLTIP_STYLE} labelStyle={{ color: '#e2e8f0' }} itemStyle={{ color: '#e2e8f0' }} formatter={(value: number) => [value.toLocaleString(), '']} />
        </RCPieChart>
      </ResponsiveContainer>
    </div>
  )
);
PieChart.displayName = 'PieChart';

// Metric Trend Component
export const MetricTrend = ({ value, trend, label }: { value: string | number; trend?: number; label?: string }) => (
  <div className="flex items-center gap-2">
    <span className="text-2xl font-bold text-white">{value}</span>
    {trend !== undefined && (
      <span className={`flex items-center gap-1 text-sm font-medium ${trend > 0 ? 'text-emerald-400' : trend < 0 ? 'text-rose-400' : 'text-gray-500'}`}>
        {trend > 0 ? <TrendingUp className="w-4 h-4" /> : trend < 0 ? <TrendingDown className="w-4 h-4" /> : null}
        {Math.abs(trend)}%
      </span>
    )}
    {label && <span className="text-xs text-gray-500">{label}</span>}
  </div>
);
